from fastapi import FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from database import init_db, get_db
from models import BookCreate, BookUpdate, BookResponse

app = FastAPI(title="BookTrack")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_methods=["*"],
    allow_headers=["*"],
)

init_db()


def _row_to_book(row):
    return BookResponse(
        id=row["id"],
        title=row["title"],
        author=row["author"],
        status=row["status"],
    )


@app.get("/api/books", response_model=list[BookResponse])
def get_books():
    with get_db() as conn:
        rows = conn.execute(
            "SELECT * FROM books ORDER BY id DESC"
        ).fetchall()
    return [_row_to_book(r) for r in rows]


@app.post("/api/books", response_model=BookResponse, status_code=201)
def add_book(book: BookCreate):
    with get_db() as conn:
        cursor = conn.execute(
            "INSERT INTO books (title, author, status) VALUES (?, ?, ?)",
            (book.title, book.author, book.status),
        )
        row = conn.execute("SELECT * FROM books WHERE id = ?", (cursor.lastrowid,)).fetchone()
    return _row_to_book(row)


@app.patch("/api/books/{book_id}", response_model=BookResponse)
def update_status(book_id: int, update: BookUpdate):
    with get_db() as conn:
        existing = conn.execute("SELECT * FROM books WHERE id = ?", (book_id,)).fetchone()
        if not existing:
            raise HTTPException(status_code=404, detail="Libro non trovato")
        conn.execute(
            "UPDATE books SET status = ? WHERE id = ?",
            (update.status, book_id),
        )
        row = conn.execute("SELECT * FROM books WHERE id = ?", (book_id,)).fetchone()
    return _row_to_book(row)


@app.delete("/api/books/{book_id}", status_code=204)
def delete_book(book_id: int):
    with get_db() as conn:
        existing = conn.execute("SELECT * FROM books WHERE id = ?", (book_id,)).fetchone()
        if not existing:
            raise HTTPException(status_code=404, detail="Libro non trovato")
        conn.execute("DELETE FROM books WHERE id = ?", (book_id,))
    return None

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  server: {
    port: 3000,
    proxy: {
      '/api': 'http://localhost:8000'
    }
  }
});

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import { useState, useEffect, useCallback } from 'react';

const STATUS_LABELS = {
  'to-read': 'Da leggere',
  'reading': 'Lettura',
  'done': 'Letto',
};

const STATUS_ORDER = ['to-read', 'reading', 'done'];

function cycleStatus(status) {
  const idx = STATUS_ORDER.indexOf(status);
  return STATUS_ORDER[(idx + 1) % STATUS_ORDER.length];
}

export default function App() {
  const [books, setBooks] = useState([]);
  const [title, setTitle] = useState('');
  const [author, setAuthor] = useState('');
  const [status, setStatus] = useState('to-read');
  const [loading, setLoading] = useState(false);

  const fetchBooks = useCallback(async () => {
    try {
      const res = await fetch('/api/books');
      const data = await res.json();
      setBooks(data);
    } catch (e) {
      console.error('Errore nel caricamento:', e);
    }
  }, []);

  useEffect(() => {
    fetchBooks();
  }, [fetchBooks]);

  const handleAdd = async (e) => {
    e.preventDefault();
    if (!title.trim() || !author.trim()) return;
    setLoading(true);
    try {
      const res = await fetch('/api/books', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: title.trim(), author: author.trim(), status }),
      });
      if (res.ok) {
        setTitle('');
        setAuthor('');
        setStatus('to-read');
        await fetchBooks();
      }
    } catch (e) {
      console.error('Errore nell\'aggiunta:', e);
    }
    setLoading(false);
  };

  const handleStatusChange = async (id, newStatus) => {
    try {
      const res = await fetch(`/api/books/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: newStatus }),
      });
      if (res.ok) await fetchBooks();
    } catch (e) {
      console.error('Errore nell\'aggiornamento:', e);
    }
  };

  const handleDelete = async (id) => {
    try {
      const res = await fetch(`/api/books/${id}`, { method: 'DELETE' });
      if (res.ok) await fetchBooks();
    } catch (e) {
      console.error('Errore nella cancellazione:', e);
    }
  };

  const counts = {
    'to-read': books.filter(b => b.status === 'to-read').length,
    'reading': books.filter(b => b.status === 'reading').length,
    'done': books.filter(b => b.status === 'done').length,
  };

  return (
    <div>
      <h1>📚 Book<span>Track</span></h1>

      <form className="add-form" onSubmit={handleAdd}>
        <input
          type="text"
          placeholder="Titolo del libro"
          value={title}
          onChange={e => setTitle(e.target.value)}
        />
        <input
          type="text"
          placeholder="Autore"
          value={author}
          onChange={e => setAuthor(e.target.value)}
        />
        <select value={status} onChange={e => setStatus(e.target.value)}>
          <option value="to-read">Da leggere</option>
          <option value="reading">Lettura</option>
          <option value="done">Letto</option>
        </select>
        <button type="submit" disabled={loading}>
          {loading ? 'Aggiungendo...' : 'Aggiungi'}
        </button>
      </form>

      <div className="stats">
        <div className="stat to-read">
          <div className="num">{counts['to-read']}</div>
          <div className="label">Da leggere</div>
        </div>
        <div className="stat reading">
          <div className="num">{counts['reading']}</div>
          <div className="label">Lettura</div>
        </div>
        <div className="stat done">
          <div className="num">{counts['done']}</div>
          <div className="label">Letto</div>
        </div>
      </div>

      <div className="book-list">
        {books.length === 0 && (
          <div className="empty">Nessun libro ancora. Aggiungine uno!</div>
        )}
        {books.map(book => (
          <div className="book-card" key={book.id}>
            <div className="book-info">
              <div className="book-title">{book.title}</div>
              <div className="book-author">{book.author}</div>
            </div>
            <button
              className={`book-status ${book.status}`}
              onClick={() => handleStatusChange(book.id, cycleStatus(book.status))}
              title="Clicca per cambiare stato"
            >
              {STATUS_LABELS[book.status]}
            </button>
            <button
              className="delete-btn"
              onClick={() => handleDelete(book.id)}
              title="Elimina"
            >
              ✕
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

